const ml=a=>`{${a.map(x=>Array.isArray(x)?ml(x):typeof x==='boolean'||typeof x==='number'?String(x):mt(x)).join(', ')}}`;
const parameter=(name,expression,type='Text')=>({name,kind:'m',expression,annotations:[{name:'IsParameterQuery',value:'True'},{name:'Type',value:type},{name:'IsParameterQueryRequired',value:'True'}]});
const expr=(name,expression)=>({name,kind:'m',expression});
